import{_ as a,o as s,c as n,a4 as e}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"Java（Spring Boot）高并发与高可用设计","description":"","frontmatter":{},"headers":[],"relativePath":"service/java-high-concurrency.md","filePath":"service/java-high-concurrency.md"}'),r={name:"service/java-high-concurrency.md"};function d(o,t,i,l,p,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="java-spring-boot-高并发与高可用设计" tabindex="-1">Java（Spring Boot）高并发与高可用设计 <a class="header-anchor" href="#java-spring-boot-高并发与高可用设计" aria-label="Permalink to &quot;Java（Spring Boot）高并发与高可用设计&quot;">​</a></h1><blockquote><p><strong>优先级：P1</strong> — Java 后端的主流高并发框架是 Spring Boot（单体/微服务都能落）。核心认知：<strong>Java 是&quot;原生支持并发编程&quot;，但高并发是架构设计的结果</strong>——语言给能力，设计给容量。</p></blockquote><h2 id="一、java-的并发模型-先看清地基" tabindex="-1">一、Java 的并发模型（先看清地基） <a class="header-anchor" href="#一、java-的并发模型-先看清地基" aria-label="Permalink to &quot;一、Java 的并发模型（先看清地基）&quot;">​</a></h2><p>传统 Spring Boot（Servlet 容器 Tomcat）模型：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个请求 = 一个线程（Tomcat 线程池，默认 200）</span></span>
<span class="line"><span>  ├─ IO 阻塞时线程睡眠，OS 切换别的线程</span></span>
<span class="line"><span>  └─ 并发上限 ≈ 线程数（受内存/切换成本约束，通常几千到顶）</span></span></code></pre></div><p><strong>演进</strong>：JDK 21 <strong>虚拟线程</strong>（百万级轻量线程，每请求一虚拟线程）+ <strong>WebFlux</strong>（响应式，类似 Node 事件模型）——都在往&quot;更省资源的高并发&quot;走。</p><blockquote><p><strong>高并发的第一原则</strong>：瓶颈通常不在 Java 代码，而在 <strong>DB/连接池/外部依赖</strong>——先定位瓶颈在哪，再谈优化。</p></blockquote><h2 id="二、高并发设计-分层手段" tabindex="-1">二、高并发设计（分层手段） <a class="header-anchor" href="#二、高并发设计-分层手段" aria-label="Permalink to &quot;二、高并发设计（分层手段）&quot;">​</a></h2><p><strong>① 单机层</strong>：</p><table tabindex="0"><thead><tr><th>手段</th><th>做什么</th></tr></thead><tbody><tr><td>线程池调优</td><td>Tomcat 线程数、队列大小（别默认，按压测调）</td></tr><tr><td>连接池调优</td><td>Druid/HikariCP 的 max-active（数据库连接才是真稀缺）</td></tr><tr><td>异步化</td><td>非核心逻辑异步（MQ / @Async），别占请求线程</td></tr><tr><td>并发工具</td><td>ConcurrentHashMap、线程池、锁用得对</td></tr></tbody></table><p><strong>② 架构层</strong>（高并发的真正主力）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Redis 缓存    → 扛热点读（挡住 90% 重复查询打 DB）</span></span>
<span class="line"><span>MQ 削峰       → 突发流量先入队，消费者匀速处理（下单/秒杀）</span></span>
<span class="line"><span>水平扩展      → 多实例 + 负载均衡（加机器=加并发，这是最优解）</span></span>
<span class="line"><span>数据层        → 读写分离（主写从读）、分库分表（单库瓶颈才上）</span></span>
<span class="line"><span>限流          → Sentinel/Guava 令牌桶，超阈值直接拒绝（保护系统）</span></span></code></pre></div><h2 id="三、高可用设计-不挂-挂了能救" tabindex="-1">三、高可用设计（不挂/挂了能救） <a class="header-anchor" href="#三、高可用设计-不挂-挂了能救" aria-label="Permalink to &quot;三、高可用设计（不挂/挂了能救）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>做什么</th><th>对应 mall/12306</th></tr></thead><tbody><tr><td><strong>集群 + 负载均衡</strong></td><td>多实例 + LB + 健康检查</td><td>多台 mall-admin 前面挂 nginx</td></tr><tr><td><strong>无状态化</strong></td><td>登录态/会话外置（Redis/JWT）</td><td>mall 的 JWT 无状态天然可扩</td></tr><tr><td><strong>熔断降级</strong></td><td>依赖挂了走兜底（Sentinel/Resilience4j）</td><td>缓存失败降级查库（mall 的 @CacheException）</td></tr><tr><td><strong>限流</strong></td><td>超阈值拒绝，保护自己</td><td>秒杀场景必备</td></tr><tr><td><strong>幂等</strong></td><td>重复请求不重复扣款/下单</td><td>订单防重</td></tr><tr><td><strong>分布式锁</strong></td><td>并发抢资源（库存扣减）</td><td>12306 锁库存</td></tr><tr><td><strong>监控</strong></td><td>Actuator/日志（ELK）/指标（Prometheus）</td><td>先能看见，才能救</td></tr></tbody></table><h2 id="四、演进路径-从小到大的容量路线" tabindex="-1">四、演进路径（从小到大的容量路线） <a class="header-anchor" href="#四、演进路径-从小到大的容量路线" aria-label="Permalink to &quot;四、演进路径（从小到大的容量路线）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单体单机（mall） → 单机多实例 + nginx（加机器）</span></span>
<span class="line"><span>  → Redis 缓存扛读 + MQ 削峰</span></span>
<span class="line"><span>  → 读写分离 / 分库分表（DB 瓶颈）</span></span>
<span class="line"><span>  → 微服务拆分（12306，按业务域拆 + 独立扩容）</span></span></code></pre></div><p><strong>每一步解决一个瓶颈</strong>，别一开始就上微服务——先加缓存/加机器，便宜且快。</p><h2 id="五、实践清单" tabindex="-1">五、实践清单 <a class="header-anchor" href="#五、实践清单" aria-label="Permalink to &quot;五、实践清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>清单项</th><th>为什么</th></tr></thead><tbody><tr><td>先定位瓶颈</td><td>代码/DB/连接池？优化错地方白干</td></tr><tr><td>缓存扛热点</td><td>读多写少先上 Redis</td></tr><tr><td>MQ 削峰</td><td>突发写用队列匀速消化</td></tr><tr><td>加机器 &gt; 调代码</td><td>水平扩展是最优解，代码优化是瓶颈期才做</td></tr><tr><td>连接池不是越大越好</td><td>连接数是 DB 上限，超了排队更糟</td></tr><tr><td>无状态化前置</td><td>不然扩不了实例</td></tr><tr><td>限流/熔断/降级</td><td>高可用的三件套，出事能活</td></tr><tr><td>监控先上线</td><td>容量规划靠数据，不是拍脑袋</td></tr></tbody></table><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><blockquote><p>Java 高并发的正确姿势：<strong>先承认&quot;语言不是瓶颈，架构才是&quot;</strong>——单机靠线程池/异步压榨，真正容量来自 <strong>Redis 扛读 + MQ 削峰 + 多实例水平扩展 + 数据层拆分</strong>；高可用靠<strong>集群 + 无状态 + 限流熔断降级 + 监控</strong>。演进路径&quot;单体 → 加缓存/加机器 → 分库 → 微服务&quot;，一步解决一个瓶颈。</p></blockquote><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/knowledge/service/node-vs-java.html">Node.js vs Java 后端选型</a> - 并发模型对比</li><li><a href="/knowledge/service/redis-intro.html">Redis 入门</a> - 高并发第一层（缓存）</li><li><a href="/knowledge/service/mq-intro.html">消息队列（Kafka）入门</a> - 削峰</li><li><a href="/knowledge/service/distributed-basics.html">分布式基础</a> - 集群/分布式锁</li></ul>`,23)])])}const u=a(r,[["render",d]]);export{g as __pageData,u as default};
